#include AUDIT_RUNTIME

I pys_obj_eq(I c, I a, I b) { (void)c; return a == b; }
I pys_obj_cmp(I c, I op, I a, I b) { (void)c; (void)op; return a < b ? -1 : a > b; }
Str *pys_obj_repr(I c, I a, I b) { (void)c; (void)a; (void)b; return cstr("<object>"); }
static List *kept;
static I *roots[] = {(I *)&kept};
__attribute__((noinline)) static void scrub(void) {
  volatile I pad[4096];
  for (I i = 0; i < 4096; i++) pad[i] = 0;
  collect();
  if (pad[0]) abort();
}
__attribute__((noinline)) static void churn(int scanned) {
  for (I i = 0; i < 512; i++) {
    if (scanned) pys_list_new(8192); else pys_list_new_atomic(8192);
  }
}
int main(int argc, char **argv) {
  gc_init(__builtin_frame_address(0), roots, 1);
  const char *mode = argc > 1 ? argv[1] : "atomic";
  I before = gc_n;
  if (!strcmp(mode, "scanned-candidate")) pys_alloc(5 << 20);
  else if (!strcmp(mode, "mixed-candidate")) { pys_alloc_atomic(3 << 20); pys_alloc(2 << 20); }
  else if (!strcmp(mode, "atomic-candidate")) pys_alloc_atomic(5 << 20);
  else if (!strcmp(mode, "ordinary-candidate")) pys_alloc(32 << 20);
  else if (!strcmp(mode, "live")) {
    kept = pys_list_new(128);
    for (I i = 0; i < 128; i++) pys_list_append(kept, (I)pys_list_new_atomic(8192));
    scrub(); before = gc_n; gc_peak = gc_heap; churn(0);
  }
  else if (!strcmp(mode, "small")) {
    for (I i = 0; i < (48 << 20) / 64; i++) pys_alloc_atomic(56);
  }
  else if (!strcmp(mode, "mixed")) {
    for (I i = 0; i < 160; i++) {
      pys_list_new_atomic(8192);
      for (I j = 0; j < 3 * 1024; j++) pys_alloc_atomic(56);
    }
  }
  else churn(!strcmp(mode, "scanned"));
  printf("{\"case\":\"%s\",\"collections\":%lld,\"heap_peak_bytes\":%lld,\"heap_end_bytes\":%lld}\n",
         mode, (long long)(gc_n-before), (long long)gc_peak, (long long)gc_heap);
  return 0;
}
